  { id: 300159, level: "C2", pos: "idiom", en: "pass the buck", fa: "\u0645\u0633\u0626\u0648\u0644\u06CC\u062A \u0631\u0627 \u06AF\u0631\u062F\u0646 \u062F\u06CC\u06AF\u0631\u06CC \u0627\u0646\u062F\u0627\u062E\u062A\u0646" },
  { id: 300181, level: "C2", pos: "idiom", en: "play it by ear", fa: "\u0628\u062F\u0648\u0646 \u0628\u0631\u0646\u0627\u0645\u0647\u200C\u06CC \u0627\u0632 \u067E\u06CC\u0634\u060C \u0628\u062F\u0627\u0647\u0647 \u0639\u0645\u0644 \u06A9\u0631\u062F\u0646" },
  { id: 300160, level: "C2", pos: "idiom", en: "pull strings", fa: "\u0627\u0632 \u0646\u0641\u0648\u0630 \u062E\u0648\u062F \u0627\u0633\u062A\u0641\u0627\u062F\u0647 \u06A9\u0631\u062F\u0646" },
  { id: 300161, level: "C2", pos: "idiom", en: "put the cart before the horse", fa: "\u06A9\u0627\u0631\u0647\u0627 \u0631\u0627 \u0646\u0627\u0645\u0631\u062A\u0628 \u0648 \u0628\u0631\u0639\u06A9\u0633 \u0627\u0646\u062C\u0627\u0645 \u062F\u0627\u062F\u0646" },
  { id: 300182, level: "C2", pos: "idiom", en: "put your foot in your mouth", fa: "\u0633\u0648\u062A\u06CC \u062F\u0627\u062F\u0646\u060C \u062D\u0631\u0641 \u0646\u0627\u0645\u0646\u0627\u0633\u0628 \u0632\u062F\u0646" },
  { id: 300183, level: "C2", pos: "idiom", en: "read someone like a book", fa: "\u06A9\u0627\u0645\u0644\u0627\u064B \u06A9\u0633\u06CC \u0631\u0627 \u0634\u0646\u0627\u062E\u062A\u0646" },
  { id: 300162, level: "C2", pos: "idiom", en: "see the writing on the wall", fa: "\u0646\u0634\u0627\u0646\u0647\u200C\u0647\u0627\u06CC \u0648\u0627\u0636\u062D \u06CC\u06A9 \u0627\u062A\u0641\u0627\u0642 \u0628\u062F \u0631\u0627 \u062F\u06CC\u062F\u0646" },
  { id: 300163, level: "C2", pos: "idiom", en: "separate the wheat from the chaff", fa: "\u062E\u0648\u0628 \u0631\u0627 \u0627\u0632 \u0628\u062F \u062A\u0634\u062E\u06CC\u0635 \u062F\u0627\u062F\u0646" },
  { id: 300164, level: "C2", pos: "idiom", en: "steal someone's thunder", fa: "\u0627\u0641\u062A\u062E\u0627\u0631 \u0632\u062D\u0645\u062A \u06A9\u0633\u06CC \u062F\u06CC\u06AF\u0631 \u0631\u0627 \u0628\u0631\u062F\u0646" },
  { id: 300165, level: "C2", pos: "idiom", en: "take something at face value", fa: "\u0686\u06CC\u0632\u06CC \u0631\u0627 \u0647\u0645\u0627\u0646\u200C\u0637\u0648\u0631 \u06A9\u0647 \u0647\u0633\u062A \u067E\u0630\u06CC\u0631\u0641\u062A\u0646" },
  { id: 300166, level: "C2", pos: "idiom", en: "the best of both worlds", fa: "\u062F\u0627\u0634\u062A\u0646 \u0645\u0632\u0627\u06CC\u0627\u06CC \u0647\u0631 \u062F\u0648 \u0637\u0631\u0641" },
  { id: 300167, level: "C2", pos: "idiom", en: "the last straw", fa: "\u0622\u062E\u0631\u06CC\u0646 \u0636\u0631\u0628\u0647\u200C\u0627\u06CC \u06A9\u0647 \u0635\u0628\u0631 \u0631\u0627 \u0644\u0628\u0631\u06CC\u0632 \u0645\u06CC\u200C\u06A9\u0646\u062F" },
  { id: 300168, level: "C2", pos: "idiom", en: "through thick and thin", fa: "\u062F\u0631 \u062E\u0648\u0634\u06CC \u0648 \u0646\u0627\u062E\u0648\u0634\u06CC\u060C \u0647\u0645\u06CC\u0634\u0647" }
